// Node structure
struct Node {
    int data;
    struct Node *left;
    struct Node *right;
} 

// Queue node for level order traversal
struct QueueNode {
    Node* treeNode;
    struct QueueNode* next;
}

// Queue structure
struct Queue {
    QueueNode* front;
    QueueNode* rear;
} 

// Create a new tree node
Node* newNode(int val) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = val;
    node->left = node->right = NULL;
    return node;
}

// Queue functions
Queue* createQueue() {
    Queue* q = (Queue*)malloc(sizeof(Queue));
    q->front = q->rear = NULL;
    return q;
}

bool isEmpty(Queue* q) {
    return q->front == NULL;
}

void enqueue(Queue* q, Node* node) {
    QueueNode* temp = (QueueNode*)malloc(sizeof(QueueNode));
    temp->treeNode = node;
    temp->next = NULL;
    if (q->rear == NULL) {
        q->front = q->rear = temp;
        return;
    }
    q->rear->next = temp;
    q->rear = temp;
}

Node* dequeue(Queue* q) {
    if (isEmpty(q))
        return NULL;
    QueueNode* temp = q->front;
    Node* node = temp->treeNode;
    q->front = q->front->next;
    if (q->front == NULL)
        q->rear = NULL;
    free(temp);
    return node;
}

bool isIdentical(Node* r1, Node* r2) {
    if (r1 == NULL && r2 == NULL)
        return true;

    if (r1 == NULL || r2 == NULL)
        return false;

    // Use two queues for level order traversal
    Queue* q1 = createQueue();
    Queue* q2 = createQueue();
    enqueue(q1, r1);
    enqueue(q2, r2);

    while (!isEmpty(q1) && !isEmpty(q2)) {
        Node* node1 = dequeue(q1);
        Node* node2 = dequeue(q2);

        // Check if the current nodes are identical
        if (node1->data != node2->data)
            return false;

        // Check left children
        if (node1->left && node2->left) {
            enqueue(q1, node1->left);
            enqueue(q2, node2->left);
        } else if (node1->left || node2->left) {
            return false;
        }

        // Check right children
        if (node1->right && node2->right) {
            enqueue(q1, node1->right);
            enqueue(q2, node2->right);
        } else if (node1->right || node2->right) {
            return false;
        }
    }
    // If both queues are empty, the trees are identical
    return isEmpty(q1) && isEmpty(q2);
}

